// YSH (Oils' new shell): backend + emitter. Invoked like the POSIX family (`ysh -c`), but YSH rejects the POSIX
// '\'' idiom, so literals are J8 b'...' strings (\\ \' \yXX escapes).
// Every value is a YSH expression: J8 b'...' literals, `var`/`setvar`/`setglobal`, typed procs `proc f (; a, b)`
// returning through the global _r, `$[expr]` in command words. YSH's `//` truncates like C but refuses a negative
// divisor, so division and remainder go through the _div/_mod funcs defined in the header when used.
#include "shell.hpp"
#include "emit_dialect.hpp"
#include <set>

namespace forge::script {
namespace {
std::string jq(const std::string& s) {   // J8 b'...' literal: \\ \' and \yXX for control / non-ASCII bytes
    static const char* hx = "0123456789abcdef";
    std::string o = "b'";
    for (unsigned char c : s) {
        if (c == '\\' || c == '\'') { o += '\\'; o += char(c); }
        else if (c == '\n') o += "\\n";
        else if (c == '\t') o += "\\t";
        else if (c == '\r') o += "\\r";
        else if (c < 0x20 || c >= 0x7f) { o += "\\y"; o += hx[c >> 4]; o += hx[c & 15]; }
        else o += char(c);
    }
    return o + "'";
}
struct ysh_dialect : block_dialect {
    std::set<std::string> need;
    std::string header() override {
        std::string h = "#!/usr/bin/env ysh\n# generated by `forge script --emit ysh`; runs without FORGE\nvar _r = ''\n";
        if (need.count("div")) h += "func _div(a, b) { if (b < 0) { return (-(a // -b)) } return (a // b) }\n";
        if (need.count("mod")) h += "func _mod(a, b) { return (a - _div(a, b) * b) }\n";
        return h;
    }
    std::string ident(const std::string& n) override {
        static const std::set<std::string> reserved = {"var", "setvar", "setglobal", "const", "proc", "func", "if", "else", "elif", "for", "while",
            "return", "break", "continue", "case", "true", "false", "null", "and", "or", "not", "in", "is", "call", "ENV", "len", "str", "int",
            "join", "split", "write", "echo", "exit", "test", "read", "get", "type", "list", "dict", "bool", "float", "print", "abs", "max", "min",
            "PWD", "HOME", "PATH", "IFS", "_reply", "_status", "_r", "_div", "_mod", "io", "vm", "Bool", "Int", "Str", "List", "Dict"};
        return reserved.count(n) ? n + "_" : n;
    }
    std::string w(const std::string& v) const { return "$[" + v + "]"; }   // expression -> one command word
    // "(" + s + ")" that never starts with "((" (YSH rejects bash's (( )) arithmetic, e.g. in `if ((a) and b)`)
    static std::string P(const std::string& s) { return (s.starts_with("(") ? "( " : "(") + s + ")"; }
    std::string s_lit(const std::string& s) override { return jq(s); }
    std::string ref(const std::string& n, ety, bool) override { return n; }
    std::string arith(char op, const std::string& a, const std::string& b) override {
        if (op == '/') { need.insert("div"); return "_div(" + a + ", " + b + ")"; }
        if (op == '%') { need.insert("div"); need.insert("mod"); return "_mod(" + a + ", " + b + ")"; }
        return P(a + " " + op + " " + b);
    }
    std::string neg(const std::string& a) override { return "(-" + a + ")"; }
    std::string concat(const std::vector<std::string>& p) override {
        if (p.empty()) return "''";
        std::string o; for (auto& x : p) o += (o.empty() ? "" : " ++ ") + x; return P(o);
    }
    std::string i2s(const std::string& i) override { return "str(" + i + ")"; }
    std::string s2i(const std::string& s) override { return "int(" + s + ")"; }
    std::string slen(const std::string& s) override { return "len(" + s + ")"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        if (ints && op != "==" && op != "!=") return P(a + " " + op + " " + b);
        if (op == "==") return P(a + " === " + b);
        if (op == "!=") return P(a + " !== " + b);
        no("string ordering with " + op);
    }
    std::string c_and(const std::string& a, const std::string& b) override { return P(a + " and " + b); }
    std::string c_or(const std::string& a, const std::string& b) override { return P(a + " or " + b); }
    std::string c_not(const std::string& a) override { return "(not " + a + ")"; }
    std::string c_bool(bool v) override { return v ? "true" : "false"; }
    std::string truthy(const std::string& v) override { return P(v + " === 'true'"); }
    void let(const std::string& n, const std::string& v, ety, bool global, bool decl) override {
        if (cx->in_fn && global) L("setglobal " + n + " = " + v);
        else L((decl ? "var " : "setvar ") + n + " = " + v);
    }
    void print(const std::string& v, bool nl, bool err) override { L(std::string("write ") + (nl ? "" : "--end '' ") + "-- " + w(v) + (err ? " >&2" : "")); }
    std::string cond(const std::string& c) const { return c.size() > 1 && c.front() == '(' && !c.starts_with("((") ? c : P(c); }
    void if_(const std::string& c) override { open("if " + cond(c) + " {"); }
    void else_() override { mid("} else {"); }
    void end_if() override { close("}"); }
    void while_(const std::string& c) override { open("while " + cond(c) + " {"); }
    void end_while() override { close("}"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override {
        std::string s; for (auto& i : items) s += (s.empty() ? "" : ", ") + i;
        open("for " + v + " in ([" + s + "]) {");
    }
    void end_for() override { close("}"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        std::string s; for (auto& p : ps) s += (s.empty() ? "" : ", ") + p;
        open(ps.empty() ? "proc " + name + " {" : "proc " + name + " (; " + s + ") {");
    }
    void end_fn() override { close("}"); }
    void ret(const std::string& v) override { if (!v.empty()) L("setglobal _r = " + v); L("return 0"); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety rt) override {
        std::string s; for (auto& x : a) s += (s.empty() ? "" : ", ") + x;
        L(a.empty() ? name : name + " " + P(s));
        if (!want) return "";
        auto t = cx->tmp(); let(t, "_r", rt, !cx->in_fn, true); return t;
    }
    void exit_(const std::string& c) override { L("exit " + w(c)); }
    std::string env(const std::string& n, const std::string& d) override { return "get(ENV, " + n + ", " + d + ")"; }
    void setenv(const std::string& n, const std::string& v) override { L(std::string(cx->in_fn ? "setglobal" : "setvar") + " ENV[" + n + "] = " + v); }
    std::string test_path(const std::string& p, char k) override {
        return "($(if test -" + std::string(1, k) + " " + w(p) + " { echo 1 } else { echo 0 }) === '1')";
    }
    void mkdir(const std::string& p) override { L("mkdir -p -- " + w(p)); }
    void remove(const std::string& p) override { L("rm -rf -- " + w(p)); }
    void write(const std::string& p, const std::string& s, bool app) override { L("write --end '' -- " + w(s) + (app ? " >> " : " > ") + w(p)); }
    std::string read(const std::string& p) override {
        auto t = cx->tmp(); let(t, "''", ety::Str, !cx->in_fn, true);
        if (cx->in_fn) L("read --all (&" + t + ") < " + w(p));
        else L("read --all < " + w(p) + "; setvar " + t + " = _reply");
        return t;
    }
    std::string cwd() override { return "$(pwd -P)"; }
    std::string platform() override {
        return "$(sh -c " + jq("case $(uname -s) in Linux) if [ -n \"${ANDROID_ROOT-}\" ]; then echo android; else echo linux; fi;; Darwin) echo macos;; "
                              "FreeBSD) echo freebsd;; MINGW*|MSYS*|CYGWIN*|Windows_NT) echo windows;; *) echo other;; esac") + ")";
    }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        bool g = !cx->in_fn;
        auto t = cx->tmp();
        // sh appends "\x1c<code>" so $(...) keeps the output's trailing newlines and the code travels with it
        std::string wrap = host ? "(" + cx->exe + " -c \"$1\"); printf '\\034%d' \"$?\"" : sh_wrapper();
        let(t, "$(sh -c " + jq(wrap) + " _ " + w(cmd) + ").split(b'\\y1c')", ety::Str, g, true);
        let(o, "join(" + t + "[:-1], b'\\y1c')", ety::Str, g, false);
        let(c, "int(" + t + "[-1])", ety::Int, g, false);
    }
    std::string sh_quote(const std::string& v) override { return "(b'\\'' ++ " + v + ".replace(b'\\'', b'\\'\\\\\\'\\'') ++ b'\\'')"; }
};
} // namespace
} // namespace forge::script

void forge_shell_register_ysh(forge::script::shell_registry& r) {
    forge::script::shell_backend b; b.name = "ysh"; b.exes = {"ysh"}; b.family = "posix"; b.golden_tested = true;
    b.notes = "Oils new shell; J8 b'...' literals";
    b.quote = forge::script::jq; b.argv = forge::script::shellq::dash_c;
    b.emitter = [] { return std::make_unique<forge::script::ysh_dialect>(); }; b.emit_ext = ".ysh"; b.emit_tested = true;
    r.add(std::move(b));
}
